// Input: structured JSON like in your screenshot
// Output: { profile_clean_string: "..." }

const d = $json;

// helpers
const isStr = v => typeof v === 'string';
const asStr = v => {
  if (v == null) return '';
  if (Array.isArray(v)) return v.map(asStr).filter(Boolean).join(', ');
  if (typeof v === 'object') return '';
  return String(v).trim();
};
const clean = v => {
  const s = asStr(v);
  if (!s) return '';
  if (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined') return '';
  return s;
};
const uniqJoin = (arr, sep = ' | ') => {
  const out = [];
  const seen = new Set();
  for (const v of arr.map(x => (x || '').trim()).filter(Boolean)) {
    const key = v.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      out.push(v);
    }
  }
  return out.join(sep);
};

// read fields with fallbacks to your schema
const profileUrl  = clean(d.linkedinUrl || d.profileUrl || d.url);
const fullName    = clean(d.fullName || [d.firstName, d.lastName].filter(Boolean).join(' '));
const headline    = clean(d.headline);
const jobTitle    = clean(d.jobTitle || d.currentTitle);
const companyName = clean(d.companyName);
const location    = clean(d.addressWithCountry || d.addressWithoutCountry || d.location || [d.city, d.country].filter(Boolean).join(', '));
const connections = clean(d.connections);
const followers   = clean(d.followers);
const about       = clean(d.about || d.summary || d.bio);
const tenureTxt   = clean(d.currentJobDuration) || (d.currentJobDurationInYrs != null ? `${d.currentJobDurationInYrs} yrs` : '');

// skills: can be comma string, array of strings, or array of {name:...}
let skillsRaw = d.topSkillsByEndorsements || d.skills;
let skills = [];
if (isStr(skillsRaw)) {
  skills = skillsRaw.split(',').map(s => s.trim()).filter(Boolean);
} else if (Array.isArray(skillsRaw)) {
  skills = skillsRaw
    .map(s => (typeof s === 'object' && s ? (s.name || s.skill || '') : s))
    .map(asStr)
    .filter(Boolean);
}
skills = Array.from(new Set(skills.map(s => s.trim())));

// images
const imgSmall = clean(d.profilePic || d.profileImage || d.image);
const imgLarge = clean(d.profilePicLarge || d.profileImageLarge);

// compose labeled parts
const parts = [];
if (profileUrl) parts.push(`LinkedIn: ${profileUrl}`);
if (fullName)   parts.push(`Name: ${fullName}`);
if (headline)   parts.push(`Headline: ${headline}`);
if (jobTitle || companyName) {
  parts.push(`Role: ${uniqJoin([jobTitle, companyName], ' @ ')}`);
}
if (location)   parts.push(`Location: ${location}`);
if (connections || followers) {
  const cf = uniqJoin(
    [
      connections ? `Connections ${connections}` : '',
      followers ? `Followers ${followers}` : ''
    ],
    ' / '
  );
  if (cf) parts.push(cf);
}
if (tenureTxt)  parts.push(`Current tenure: ${tenureTxt}`);
if (skills.length) parts.push(`Skills: ${skills.join('; ')}`);
if (about)      parts.push(`About: ${about}`);
if (imgSmall || imgLarge) {
  parts.push(`Images: ${uniqJoin([imgSmall, imgLarge], ' | ')}`);
}

// fallback: if nothing meaningful, dump all primitives
let profile_clean_string = parts.length
  ? parts.join(' | ')
  : Object.entries(d)
      .map(([k, v]) => {
        const s = clean(v);
        return s ? `${k}: ${s}` : '';
      })
      .filter(Boolean)
      .join(' | ');

return [{ json: { profile_clean_string } }];
